components.css:
.ds-action-primary { background: #fb923c; color: #0b0f14; border: 0; border-radius: 5px;
  width: 112px; height: 30px; font: 700 11px system-ui, sans-serif; letter-spacing: 0.02em; cursor: pointer; }
.ds-action-primary:hover { box-shadow: 0 0 0 2px {c1} inset; }
.ds-action-primary:focus-visible { outline: 1px solid #fb923c; outline-offset: 3px; }

.ds-action-secondary { background: #1b2c23; color: #e3ece5; border: 0; border-radius: 5px;
  width: 112px; height: 30px; font: 400 11px system-ui, sans-serif; cursor: pointer; }
.ds-action-secondary:hover { background: #2b4033; }
.ds-action-secondary:focus-visible { outline: 1px solid #fb923c; outline-offset: 3px; }

.ds-chip { background: #1b2c23; color: #e3ece5; border: 0; border-radius: 3px;
  height: 24px; padding: 0 12px; font: 400 10px system-ui, sans-serif; cursor: pointer; }
.ds-chip:hover { background: #2b4033; }
.ds-chip--on { background: {c1}; color: #0b0f14; }
.ds-chip:focus-visible { outline: 1px solid #fb923c; outline-offset: 2px; }

.ds-param { position: relative; display: flex; align-items: center; justify-content: space-between;
  height: 25px; padding: 0 8px; border-radius: 4px; background: #1b2c23; overflow: hidden;
  font: 400 11px system-ui, sans-serif; color: #e3ece5; }
.ds-param i { position: absolute; inset: 0 auto 0 0; background: {c1}; opacity: 0.3; }
.ds-param span { position: relative; }
.ds-param:hover { box-shadow: 0 0 0 1px #354b3e inset; }

.ds-card { background: #101e17; color: #e3ece5; border: 1px solid #354b3e; border-radius: 4px; padding: 8px; }
.ds-card strong { display: block; font: 700 10px system-ui, sans-serif; letter-spacing: 0.5px; color: #93a89b; }
.ds-card p { margin: 6px 0 0; font: 400 11px system-ui, sans-serif; color: #93a89b; }

.ds-input { background: #1b2c23; color: #e3ece5; border: 1px solid #354b3e; border-radius: 4px;
  height: 25px; padding: 0 8px; font: 400 11px system-ui, sans-serif; text-align: right; width: 120px; }
.ds-input:focus { outline: none; border-color: #fb923c; box-shadow: 0 0 0 1px #fb923c inset; }

.ds-tune { display: flex; flex-direction: column; justify-content: center; height: 28px;
  padding: 0 8px; border-radius: 4px; background: #1b2c23; color: #e3ece5; font: 400 11px system-ui, sans-serif; }
.ds-tune span { font: 700 9px system-ui, sans-serif; letter-spacing: 0.5px; color: #93a89b; }
.ds-tune:hover { background: #2b4033; }
